import { stdout } from std.io;
class Box {
    width: Int32 = 10;
    height: Int32 = 20;
    construct() { }
    construct(w: Int32) { this.width = w; }
    area(): Int32 { return this.width * this.height; }
}
class User {
    construct(public name: String, private inmut id: UInt64) { }
    ident(): UInt64 { return this.id; }
}
fn main(): Void {
    mut a = Box();
    mut b = Box(3);
    mut c = Box(w: 5);
    stdout.println(a.area());
    stdout.println(b.area());
    stdout.println(c.area());
    mut u = User("Ana", 7);
    stdout.println(u.name);
    stdout.println(u.ident());
}
